create or replace function public.record_invoice_adjustment(p_invoice uuid,p_kind text,p_amount numeric,p_reason text,p_reference text default null) returns void language plpgsql security definer set search_path=public as $$ declare v_uid uuid:=auth.uid(); v_company uuid; v_role text; begin select company_id,role into v_company,v_role from public.profiles where id=v_uid; if v_company is null or v_role not in ('owner','manager') then raise exception 'Not authorised'; end if; if p_kind not in ('credit','write_off','debit') or p_amount<=0 or length(trim(p_reason))<3 then raise exception 'Invalid adjustment'; end if; if not exists(select 1 from public.invoices where id=p_invoice and company_id=v_company and status<>'void') then raise exception 'Invoice unavailable'; end if; insert into public.invoice_adjustments(company_id,invoice_id,kind,amount,reason,reference,created_by) values(v_company,p_invoice,p_kind,p_amount,trim(p_reason),p_reference,v_uid); perform public.refresh_invoice_balance(p_invoice); end $$; revoke all on function public.record_invoice_adjustment(uuid,text,numeric,text,text) from public,anon; grant execute on function public.record_invoice_adjustment(uuid,text,numeric,text,text) to authenticated;
